const importButton=document.createElement('button');importButton.className='notification';importButton.textContent='✧ 粘贴文字导入';$('new').before(importButton);
const importDialog=document.createElement('dialog');importDialog.id='importDialog';importDialog.style.width='min(760px,95vw)';importDialog.innerHTML=`<form id="importForm"><h2>把计划粘贴进来</h2><p class="subtitle" style="line-height:1.9">识别标题、分类、相对日期与每日安排。先预览确认，再添加到日历。</p><textarea id="importText" rows="7" maxlength="10000" placeholder="机器学习&#10;&#10;1.每日刷雨课堂课程&#10;2.下周分享汇报" aria-label="粘贴日程文字"></textarea><div style="display:flex;justify-content:space-between;align-items:center;margin:15px 0"><small class="subtitle">文字在当前浏览器内解析</small><button type="button" class="primary" id="parseText">识别日程</button></div><div id="importPreview"></div><div class="modalactions"><button type="button" id="closeImport">取消</button><button type="submit" class="primary hidden" id="confirmImport">确认添加</button></div></form>`;document.body.append(importDialog);let candidates=[],parsedText='';
importButton.onclick=()=>{importDialog.showModal();$('importText').focus()};$('closeImport').onclick=()=>importDialog.close();$('importText').oninput=()=>{$('importPreview').innerHTML='';$('confirmImport').classList.add('hidden');candidates=[]};
$('parseText').onclick=()=>{parsedText=$('importText').value;if(!parsedText.trim()){toast('先粘贴一段计划文字');return}candidates=parseScheduleText(parsedText);if(candidates.length>50){toast('一次最多识别 50 条，请分批导入');return}$('importPreview').innerHTML=`<p style="font-size:12px">识别到 ${candidates.length} 条候选日程 · 请补充空白字段并确认</p>`+candidates.map((c,i)=>`<section style="background:#f3f6ed;padding:16px;border-radius:9px;margin:12px 0"><label style="display:flex;align-items:center;gap:8px"><input type="checkbox" data-include="${i}" checked style="width:auto;margin:0">导入第 ${i+1} 项</label><p style="font-size:11px;color:#9c793e;line-height:1.8">${c.hints.map(esc).join('；')||'请核对识别结果'}</p><label class="field">名称<input data-i="${i}" data-f="title" value="${esc(c.title)}" maxlength="150" aria-label="第${i+1}项名称"></label><div class="fields"><label class="field">${c.repeat>1?'开始日期':'日期'}<input type="date" data-i="${i}" data-f="date" value="${c.date}"></label><label class="field">分类<select data-i="${i}" data-f="type">${Object.entries(cats).map(([k,v])=>`<option value="${k}" ${k===c.type?'selected':''}>${v[0]}</option>`).join('')}</select></label></div><div class="fields"><label class="field">开始时间<input type="time" data-i="${i}" data-f="start" value="${c.start}"></label><label class="field">结束时间<input type="time" data-i="${i}" data-f="end" value="${c.end}"></label><label class="field">连续天数<input type="number" min="1" max="90" data-i="${i}" data-f="repeat" value="${c.repeat}"></label></div><small class="subtitle">提前 15 分钟提醒 · 每日安排按上述天数生成，可逐条编辑。</small></section>`).join('');$('confirmImport').classList.toggle('hidden',!candidates.length)};
$('importForm').onsubmit=e=>{e.preventDefault();if(parsedText!==$('importText').value){toast('文字已修改，请重新识别');return}let batch=[];for(let i=0;i<candidates.length;i++){if(!document.querySelector(`[data-include="${i}"]`).checked)continue;let c={...candidates[i]};document.querySelectorAll(`[data-i="${i}"]`).forEach(el=>c[el.dataset.f]=el.value.trim());if(!c.title||!c.date||!c.start||!c.end||c.end<=c.start||!Number.isInteger(+c.repeat)||+c.repeat<1||+c.repeat>90){toast(`请补充第 ${i+1} 项的名称、日期及有效时间，连续天数为 1–90。`);return}for(let n=0;n<+c.repeat;n++){let d=new Date(c.date+'T00:00:00');d.setDate(d.getDate()+n);batch.push({id:crypto.randomUUID(),title:c.title,date:fmt(d),start:c.start,end:c.end,type:c.type,location:'',notes:'文字导入：'+c.raw,reminder:'15',done:false})}}if(!batch.length){toast('请至少勾选一条日程');return}let previous=events;events=events.concat(batch);if(!save()){events=previous;return}selected=batch[0].date;month=new Date(selected+'T00:00:00');month.setDate(1);render();importDialog.close();$('importText').value='';$('importPreview').innerHTML='';$('confirmImport').classList.add('hidden');candidates=[];toast(`已添加 ${batch.length} 项日程`)};
